-- ----------------------------------------------------------------------------
-- 5. Verifikasi
-- ----------------------------------------------------------------------------
SELECT 'Iuran (RT01):' AS label, COUNT(*)::text AS jumlah
  FROM iuran_statuses WHERE tenant_id = '00000000-0000-0000-0000-000000000011'
UNION ALL
SELECT 'Sensor pintu (RT01):', COUNT(*)::text
  FROM door_sensor_configs WHERE tenant_id = '00000000-0000-0000-0000-000000000011'
UNION ALL
SELECT 'Nomor darurat (RT01):', COUNT(*)::text
  FROM emergency_contacts WHERE tenant_id = '00000000-0000-0000-0000-000000000011';
